import React, {Component} from 'react';
import Axios from 'axios';

import UserInfo from './userEntry/userInfo';
import UserDetails from './userEntry/userDetails';
import Header from './header';

const spinner = (
  <div className="spinner">
    <div className="rect1"></div>
    <div className="rect2"></div>
    <div className="rect3"></div>
    <div className="rect4"></div>
    <div className="rect5"></div>
  </div>
);

export default class MicEntry extends Component {
  constructor(props) {
    super(props);

    this.state = {
      entry: null
    };
  }

  getMic() {
    let auth = {
      method: 'GET',
      url: `http://138.68.11.221/api/mic/${this.props.match.params.MicId}`,
      headers: {
        'Authorization': window.sessionStorage.getItem('token')
      }
    };

    return Axios(auth).then((res) => {
      this.setState({entry: res.data.data});
    }).catch((err) => {
      console.log(err);
    });
  }

  loadEntry() {
    let {entry} = this.state;

    return (
      <div className='entryContainer'>
        <div className="row">
          <div className="col-md-4"><UserInfo name={entry.hostName} status={entry.status} id={entry._id}/>
          </div>
          <div className="col-md-8">
            <UserDetails data={entry}/>
          </div>
        </div>
      </div>
    );
  }

  render() {
    if (this.state.entry == null)
      this.getMic();

    return (
      <div>
        <Header title={'User Info'}/>

        <div className='container'>
          {/*<div className='entryContainer'>        */}
          {this.state.entry == null
            ? spinner
            : this.loadEntry()}
          {/*</div>*/}
        </div>
      </div>
    );
  }
}



