import React, { Component } from 'react';
// import Date from 'react-datetime';
import moment from 'moment';
import Axios from 'axios';
import { Debounce } from 'react-throttle';
import onClickOutside from 'react-onclickoutside'

import InfiniteCalendar, {
  Calendar,
  defaultMultipleDateInterpolation,
  withMultipleDates,
} from 'react-infinite-calendar';

const MultipleDatesCalendar = withMultipleDates(Calendar);

import TimeSelector from './timeSelector';
import Header from './header';

let radioButton1 = "btn btn-primary active";
let radioButton2 = "btn btn-primary";
let placeService = null;
let currLocation = {
  latitude: null,
  longitude: null
};
const spinner = (
  <div className="spinner">
    <div className="rect1"></div>
    <div className="rect2"></div>
    <div className="rect3"></div>
    <div className="rect4"></div>
    <div className="rect5"></div>
  </div>
);
const spinner2 = (
  <div className="spinner small">
    <div className="rect1"></div>
    <div className="rect2"></div>
    <div className="rect3"></div>
    <div className="rect4"></div>
    <div className="rect5"></div>
  </div>
);

class EditMic extends Component {
  constructor(props) {
    super(props);

    this.state = {
      _id: '',
      micLoaded: false,
      firstName: '',
      lastName: '',
      email: '',
      phoneNumber: '',
      venueName: '',
      micName: '',
      days: [],
      daysPicked: 0,
      free: true,
      cost: '0',
      frequency: '',
      frequencyCount: 0,
      numDays: 1,
      removedDays: [],
      startTime: {
        hour: '',
        minute: '',
        evening: 'PM'
      },
      endTime: {
        hour: '',
        minute: '',
        evening: 'PM'
      },
      submitSuccess: true,
      locationList: [],
      venueAddress: '',
      venueLocation: {
        lat: '',
        lng: ''
      },
      noOfThumbsUp: 0,
      noOfThumbsDown: 0,
      loading: false,
      calendar: false,
      micType: '',
      customMicType: ''
    }

    this._costHandler = this._costHandler.bind(this);
  }

  handleClickOutside = (ev) => {
    this.setState({ calendar: false, locationList: []})
  }

  componentDidMount() {
    if(navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((res) => {
        currLocation.latitude = res.coords.latitude;
        currLocation.longitude = res.coords.longitude;
      }, (err) => {
        console.log(err);
      });
    }
  }
  _costHandler(free){
    this.setState({free})
  }

  updateDays(count) {
    let days = [this.state.days[0]];

    if(count.length == 0) {
      days = [this.state.days[0]];
    } else {
      if(this.state.frequency === 'weekly') {
        for(let i = 0; i < count; i++) {
          days.push(moment(days[i]).add(1, 'w').toISOString());
        }
      } else if(this.state.frequency === 'monthly') {
        for(let i = 0; i < count; i++) {
          days.push(moment(days[i]).add(1, 'months').toISOString());
        }
      }
    }

    this.setState({ days: days, frequencyCount: count });
  }

  updateStartTime(type, time) {
    console.log(type, time, this.state.startTime);
    if(type === 'hour') {
      this.setState({
        startTime: {
          hour: time,
          minute: this.state.startTime.minute,
          evening: this.state.startTime.evening
        }
      });
    } else if(type === 'minute') {
      this.setState({
        startTime: {
          hour: this.state.startTime.hour,
          minute: time,
          evening: this.state.startTime.evening
        }
      });
    } else if(type === 'evening') {
      this.setState({
        startTime: {
          hour: this.state.startTime.hour,
          minute: this.state.startTime.minute,
          evening: time
        }
      });
    }
  }

  updateEndTime(type, time) {
    if(type === 'hour') {
      this.setState({
        endTime: {
          hour: time,
          minute: this.state.endTime.minute,
          evening: this.state.endTime.evening
        }
      });
    } else if(type === 'minute') {
      this.setState({
        endTime: {
          hour: this.state.endTime.hour,
          minute: time,
          evening: this.state.endTime.evening
        }
      });
    } else if(type === 'evening') {
      this.setState({
        endTime: {
          hour: this.state.endTime.hour,
          minute: this.state.endTime.minute,
          evening: time
        }
      });
    }
  }

  updateCost(option) {
    if(option === 'false'/* && this.state.free == true*/) {
      // let tmp = radioButton1;
      // radioButton1 = radioButton2;
      // radioButton2 = tmp;
      // console.log('false');
      this.setState({ free: false });
    } else if(option === 'true'/* && this.state.free == false*/) {
      // let tmp = radioButton2;
      // radioButton2 = radioButton1;
      // radioButton1 = tmp;
      // console.log('true');
      this.setState({ free: true });
    }
  }

  updateLocation(loc) {
    this.setState({ loading: true, venueName: loc });
    placeService = new google.maps.places.PlacesService(this.refs.location);
    let locLoad = currLocation.latitude != null && currLocation.longitude != null;

    let req = {
      location: locLoad ?
        new google.maps.LatLng(currLocation.latitude, currLocation.longitude) : null,
      radius: locLoad ? '500' : null,
      query: loc
    };
    // console.log(loc);
    placeService.textSearch(req, (data, status) => {
      this.setState({ loading: false, locationList: data });
    });

    // this.setState({venueName: loc});
  }

  setLocation(loc) {
    this.refs.location.value = loc.name;
    let position = {
      lat: loc.geometry.location.lat(),
      lng: loc.geometry.location.lng()
    };
    console.log(loc);
    this.setState({ venueAddress: loc.formatted_address, venueLocation: position, locationList: [], venueName: loc.name });
  }

  loadLocationListEntries(locs) {
    return locs.map((loc, idx) => {
      // console.log(loc);
      return (
        <div key={loc.name+idx} className='locationContainer' onClick={() => this.setLocation(loc)}>
          <div className='locationName'>{loc.name}</div>
          <div className='locationAddress'>{loc.formatted_address}</div>
        </div>
      );
    })
  }

  loadLocationList() {
    let numLocs = this.state.locationList.length;
    let locs = this.state.locationList;

    return (
      <div className='location-list'>
        {this.loadLocationListEntries(locs)}
      </div>
    );
    // this.loadLocationListEntries(locs);
  }

  submitMic() {
    var micParams = {
      // mic: {
        _id: this.state._id,
        name: this.state.micName,
        venueName: this.state.venueName,
        venueAddress: this.state.venueAddress,
        location: [this.state.venueLocation.lng, this.state.venueLocation.lat],
        // location: [10,10],
        startTime: parseInt(moment(`${this.state.startTime.hour}:${this.state.startTime.minute} ${this.state.startTime.evening}`, ['h:mm A']).format('HHmm')),
        endTime: parseInt(moment(`${this.state.endTime.hour}:${this.state.endTime.minute} ${this.state.endTime.evening}`, ['h:mm A']).format('HHmm')),
        days: this.state.days,
        // repeatFrequency: this.state.frequency,
        // repeatTimes: this.state.frequencyCount,
        micType: this.state.micType !== 'Custom' ? this.state.micType : this.state.customMicType,
        free: this.state.free,
        cost: this.state.cost,
        hostName: `${this.state.firstName} ${this.state.lastName}`,
        hostEmail: this.state.email,
        hostPhone: this.state.phoneNumber,
        noOfThumbsDown: this.state.noOfThumbsDown,
        noOfThumbsUp: this.state.noOfThumbsUp
      // }
    };

    if(this.state.frequency.length > 0 && this.state.daysPicked == 1) {
      micParams.repeatFrequency = this.state.frequency;
      micParams.repeatTimes = parseInt(this.state.frequencyCount);
    }

    var auth = {
      method: 'PUT',
      url: `http://138.68.11.221/api/mic/${this.state._id}`,
      headers: {
        'Authorization' : window.sessionStorage.getItem('token')
      },
      data: micParams
    };

    console.log(JSON.stringify(micParams));
    // console.log(micParams);
    // console.log(this.state);

    if(this.state.firstName.length > 0 && this.state.lastName.length > 0 && this.state.email.length > 0 && this.state.phoneNumber.length > 0
      && this.state.venueName.length > 0  && this.state.micName.length > 0 && this.state.days.length > 0 && (
        this.state.free || (!this.state.free && this.state.cost !== '0')
      ) /*&& (
        this.state.frequency === 'custom' || (this.state.frequency !== 'custom' && this.state.frequencyCount != null)
      )*/) {
        return Axios(auth)
          .then((res) => {
            this.props.history.push('/List');
          })
          .catch((err) => {
            console.log(err);
          });
      } else {
        this.setState({ submitSuccess: false });
      }
  }

  setDays(day) {
    let formattedDay = moment(day).format("YYYY-MM-DD");
    let index = this.state.days.findIndex((day, idx) => {
      return moment(day).format('YYYY-MM-DD') === formattedDay
    })
    // console.log(index);
    if(index == -1)
      this.setState({days: this.state.days.concat([formattedDay]).sort(), daysPicked: this.state.daysPicked + 1, frequency: this.state.daysPicked+1 == 1 ? 'weekly' : ''});
    else
      this.setState({days: this.state.days.slice(0, index).concat(this.state.days.slice(index+1)).sort(), daysPicked: this.state.daysPicked - 1, frequency: this.state.daysPicked-1 == 1 ? 'weekly' : ''})
  }

  toggleCalendar() {
    if(this.state.calendar == false)
      this.setState({calendar: true});
    else
      this.setState({calendar: false});
  }

  loadMic(id) {
    let auth = {
      method: 'GET',
      url: `http://138.68.11.221/api/mic/${id}`,
      headers: {
        'Authorization' : window.sessionStorage.getItem('token')
      }
    };

    return Axios(auth)
    .then((res) => {
      let tmp = res.data.data;
      let micTypeNotCustom = (tmp.micType === 'Lotto' || tmp.micType === 'Sign Up' || tmp.micType === 'Booked');
      let startTime = moment(tmp.startTime, 'Hmm').format('hh:mm:A');
      let endTime = moment(tmp.endTime, 'Hmm').format('hh:mm:A');
      console.log(tmp);
      console.log(startTime);
      console.log(endTime);

      this.setState({
        _id: tmp._id,
        micLoaded: true,
        firstName: tmp.hostName.split(' ')[0],
        lastName: tmp.hostName.split(' ')[1],
        email: tmp.hostEmail,
        phoneNumber: tmp.hostPhone,
        venueName: tmp.venueName,
        micName: tmp.name,
        days: tmp.days,
        daysPicked: tmp.repeatFrequency && tmp.repeatFrequency.length > 0 ? 1 : 0,
        free: tmp.free,
        cost: tmp.cost,
        frequency: tmp.repeatFrequency && tmp.repeatFrequency.length > 0 ? tmp.repeatFrequency : '',
        frequencyCount: tmp.repeatTimes && tmp.repeatTimes != 0 ? tmp.repeatTimes : 0,
        startTime: {
          hour: parseInt(startTime.split(':')[0]).toString(),
          minute: startTime.split(':')[1],
          evening: startTime.split(':')[2]
        },
        endTime: {
          hour: parseInt(endTime.split(':')[0]).toString(),
          minute: endTime.split(':')[1],
          evening: endTime.split(':')[2]
        },
        submitSuccess: true,
        locationList: [],
        venueAddress: tmp.venueAddress,
        venueLocation: {lat: tmp.location[1], lng: tmp.location[0]},
        noOfThumbsDown: tmp.noOfThumbsDown,
        noOfThumbsUp: tmp.noOfThumbsUp,
        micType: micTypeNotCustom ? tmp.micType : tmp.customMicType
      });
    })
    .catch((err) => {
      console.log(err);
    });

  }

  render() {
    if(!this.state.micLoaded) {
      this.loadMic(this.props.location.pathname.split('/')[2]);
      return spinner;

    } else {

      return (
        <div>
          <Header title='Edit Mic' />

          <div className='container'>
            {/*<img src='./imgs/mic-896673_1280.png' className='micImg' />*/}
            <div className='center-div'>
              <h1 style={{color: '#d8d8d8'}}>Edit Mic</h1>
            </div>

            <div className='form-container' style={{ color: '#d8d8d8' }}>
              <form>
                <label>*First Name:</label>
                <input className='form-control' value={this.state.firstName} onChange={(ev) => this.setState({firstName: ev.target.value})}></input>

                <label>*Last Name:</label>
                <input className='form-control' value={this.state.lastName} onChange={(ev) => this.setState({lastName: ev.target.value})}></input>

                <label>*Email:</label>
                <input className='form-control' value={this.state.email} onChange={(ev) => this.setState({email: ev.target.value})}></input>

                <label>*Phone Number:</label>
                <input className='form-control' value={this.state.phoneNumber} onChange={(ev) => this.setState({phoneNumber: ev.target.value})}></input>

                <label>*Mic Type:</label>
                <select className='form-control' onChange={(ev) => this.setState({ micType: ev.target.value })}>
                  <option value='Lotto' selected={this.state.micType === 'Lotto' ? true : false}>Lotto</option>
                  <option value='Sign Up' selected={this.state.micType === 'Sign Up' ? true : false}>Sign Up</option>
                  <option value='Booked' selected={this.state.micType === 'Booked' ? true : false}>Booked</option>
                  <option value='Custom' selected={this.state.micType === 'Custom' ? true : false}>Custom</option>
                </select>

                {this.state.micType === 'Custom' ?
                  <div>
                    <input className='form-control' placeholder='Enter custom mic type' onChange={(ev) => this.setState({ customMicType: ev.target.value })}></input>
                  </div>
                  : null
                }

                <label>*Event Name:</label>
                <input className='form-control' value={this.state.micName} onChange={(ev) => this.setState({micName: ev.target.value})}></input>

                <label>*Venue Name:</label>
                {/*<Debounce time='200' handler='onChange'>*/}
                  <input className='form-control' value={this.state.venueName} ref='location' onChange={(ev) => {
                    {/*console.log(ev);*/}
                    this.updateLocation(ev.target.value)
                  }}></input>
                {/*</Debounce>*/}

                {/* Load suggested locations */}
                {/*{this.state.locationList.length > 0 ? this.loadLocationList() : null}*/}
                {this.state.loading ? spinner2 : this.state.locationList.length > 0 ? this.loadLocationList() : null}

                <label>Location</label>
                <input className="form-control" readOnly placeholder="Longitude"  value={this.state.venueLocation.lng} />
                <input className="form-control" readOnly placeholder="Latitude"
                   value={this.state.venueLocation.lat}/>

                <label>*Date(s):</label>
                <input className='form-control' value={this.state.days.map((day) => {
                    return ` ${moment(day).format('MM/DD/YY')}`
                  })}
                  readOnly
                  onClick={() => this.toggleCalendar()}
                >
                </input>

                {this.state.calendar ?
                  <MultipleDatesCalendar
                    onSelect={(ev) => this.setDays(ev) }
                    width={400}
                    height={220}
                    selected={this.state.days}
                    autoFocus={false}
                  />
                :
                  null
                }

                {this.state.daysPicked == 1 ?
                <div>
                  <label style={{ position: 'relative', float: 'left', marginTop: '10px' }}>Repeat:</label>
                  <select className='form-control' onChange={(ev) => this.setState({ frequency: ev.target.value.toLowerCase() })}>
                    <option selected={this.state.frequency === 'Weekly' ? true : false}>Weekly</option>
                    <option selected={this.state.frequency === 'Monthly' ? true : false}>Monthly</option>
                    <option selected={this.state.frequency === 'Custom' ? true : false}>Custom</option>
                  </select>
                </div>
                : null}

              {this.state.daysPicked == 1 && this.state.frequency !== 'custom' ?
                <div>
                  <label>Number of Repetitions:</label>
                  <input className='form-control' value={this.state.frequencyCount} placeholder='Enter number of repetitions' onChange={(ev) => this.updateDays(ev.target.value)}></input>
                </div>
                : null
              }

                <label>*Start time:</label>
                <TimeSelector time={this.state.startTime} updateTime={(type, time) => this.updateStartTime(type, time)}/>

                <label>*End time:</label>
                <TimeSelector time={this.state.endTime} updateTime={(type, time) => this.updateEndTime(type, time)}/>

                <label>Cost:</label>
                <div data-toggle="buttons">
                  <button className={this.state.free ? `${radioButton1} check` : `${radioButton2} check`} onClick={()=>{this._costHandler(true)}}>Free</button>
                  <button className={this.state.free ? `${radioButton2} check` : `${radioButton1} check`} onClick={()=>{this._costHandler(false)}}>Not Free</button>
                  {/*<label className={this.state.free ? `${radioButton1} check` : `${radioButton2} check`}>
                    {'Free'}
                    <input type="radio" name="options" id="option1" autoComplete="off" value={true} onClick={(ev) => this.updateCost(ev.target.value)}></input>
                  </label>*/}
                  {/*<br/>*/}
                  {/*<label className={this.state.free ? `${radioButton2} check` : `${radioButton1} check`}>
                    {'Not Free'}
                    <input type="radio" name="options" id="option2" autoComplete="off" value={false} onClick={(ev) => this.updateCost(ev.target.value)}></input>
                  </label>*/}
                </div>

                {
                  !this.state.free ?
                    <div style={{ marginTop: '10px' }}>
                      <label>Price:</label>
                      <input className='form-control' value={this.state.cost} onChange={(ev) => this.setState({ cost: ev.target.value })}></input>
                    </div>
                  :
                    null
                }

                <button className="btn btn-primary btn-lg btn-block" type="button" style={{ marginTop: '15px' }} onClick={() => this.submitMic()}>
                  Submit
                </button>

                <p style={{ textAlign: 'center', marginTop: '15px' }}>* - required field</p>

                {this.state.submitSuccess ? null : <p style={{ textAlign: 'center', marginTop: '15px', color: 'red', fontSize: '15px' }}>Please fill in all required fields!</p>}
              </form>
            </div>
          </div>
        </div>
      );
    }
  }
}

export default onClickOutside(EditMic);



