import React, { Component } from 'react';
import Moment from 'moment';

import ListEntry from './listEntry';

export default class ListContainer extends Component {
  constructor(props) {
    super(props);
  }

  loadEntries() {
    let sortedEntries = [];

    if(this.props.sort === 'Date') {
      if(this.props.sortType === 'Ascending') {
        sortedEntries = this.props.entries.sort((a, b) => {
          if(Moment(a.days[0]).isAfter(Moment(b.days[0])))
            return 1;
          else
            return -1;
        });
      } else {
        sortedEntries = this.props.entries.sort((a, b) => {
          if(Moment(a.days[0]).isBefore(Moment(b.days[0])))
            return 1;
          else
            return -1;
        });
      }
    } else if(this.props.sort === 'First Name') {
      if(this.props.sortType === 'Ascending') {
        sortedEntries = this.props.entries.sort((a, b) => {
          return a.hostName.split(' ')[0].localeCompare(b.hostName.split(' ')[0]);
        });
      } else {
        sortedEntries = this.props.entries.sort((a, b) => {
          return b.hostName.split(' ')[0].localeCompare(a.hostName.split(' ')[0]);
        });
      }
    } else if(this.props.sort === 'Last Name') {
      if(this.props.sortType === 'Ascending') {
        sortedEntries = this.props.entries.sort((a, b) => {
          return a.hostName.split(' ')[1].localeCompare(b.hostName.split(' ')[1]);
        });
      } else {
        sortedEntries = this.props.entries.sort((a, b) => {
          return b.hostName.split(' ')[1].localeCompare(a.hostName.split(' ')[1]);
        });
      }
    } else if(this.props.sort === 'City') {
      if(this.props.sortType === 'Ascending') {
        sortedEntries = this.props.entries.sort((a, b) => {
          if(a.venueAddress.split(',').length <= 1)
            return 1;
          else if(b.venueAddress.split(',').length <= 1)
            return -1;
          else
            return a.venueAddress.split(',')[1].localeCompare(b.venueAddress.split(',')[1]);
        });
      } else {
        sortedEntries = this.props.entries.sort((a, b) => {
          if(a.venueAddress.split(',').length <= 1)
            return 1;
          else if(b.venueAddress.split(',').length <= 1)
            return -1;
          else
            return b.venueAddress.split(',')[1].localeCompare(a.venueAddress.split(',')[1]);
        });
      }
    } else if(this.props.sort === 'Email') {
      if(this.props.sortType === 'Ascending') {
        sortedEntries = this.props.entries.sort((a, b) => {
          return a.hostEmail.localeCompare(b.hostEmail);
        });
      } else {
        sortedEntries = this.props.entries.sort((a, b) => {
          return b.hostEmail.localeCompare(a.hostEmail);
        });
      }
    }

    return sortedEntries.map((entry, idx) => {
      if(idx < this.props.entriesPerPage * this.props.currentPage && idx >= this.props.entriesPerPage * (this.props.currentPage-1))
        return <ListEntry key={idx} entry={entry} />
    });
  }
  
  render() {
    return (
      <div>
        <table className="table">
          <thead className='thead-default'>
            <tr>
              <th style={{width: '8vw', minWidth: '115px'}} className='col-md-2'>Date</th>
              <th style={{width: '10vw'}} className='col-sm-1'>First Name</th>
              <th style={{width: '10vw'}} className='col-sm-1'>Last Name</th>
              <th style={{width: '18vw', minWidth: '200px'}} className='col-lg-4'>Venue</th>
              <th style={{width: '9vw'}}>City</th>
              <th style={{width: '18vw'}} className='col-lg-3'>Email</th>
            </tr>
          </thead>
          <tbody style={{wordWrap: 'break-word'}}>
            { this.loadEntries() }
          </tbody>
        </table>
      </div>
    );
  }
}



